/** 이 시설이 속한 지역·유형의 항목 기준값 — 없으면 null(표본 부족·주소 결손) */
export function feeBenchmarkFor(
  facilityType: string,
  sido: string | null,
  item: string
): FeeBenchmark | null {
  if (!sido) return null;
  return FEE_BENCHMARKS[facilityType]?.[sido]?.[item] ?? null;
}
